actions.action:
tk_stav: f.tk_stav, tk_zadavatel: f.tk_zadavatel, tk_podal: f.tk_podal,
tk_firma_id: f.tk_firma_id, tk_firma_nazov: f.tk_firma_nazov, tk_predmet: f.tk_predmet;

change tk_stav value { "rozpisana" }
// Vlastnik je AUTOR pripadu, nie loggedUser() - pripad moze zalozit aj niekto
// v mene zakaznika (B28).
def autor = ((useCase.author?.id ?: "") as String)
if (!autor) {
    def u = loggedUser()
    autor = ((u?.stringId ?: "") as String)
}
if (autor) {
    change tk_zadavatel value { [autor] }
    change tk_podal value { meno_cloveka(autor) }
    def firma = firma_cloveka(autor)
    if (firma != null) {
        change tk_firma_id value { firma.stringId }
        change tk_firma_nazov value { ((firma.dataSet["f_nazov"]?.value ?: firma.title) as String) }
    }
}
changeCaseProperty("title").about { nazov(tk_predmet) }
changeCaseProperty("color").about { "grey" }

document.function:
{ def meno ->
    // Sesterska siet - identifikator nesie URI cestu (it/service_desk/...).
    def pid = useCase.processIdentifier as String
    def prefix = pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
    return prefix + meno
}

{ def userId ->
    // Firma, v ktorej clovek je. `findCases { it.dataSet... }` nefunguje,
    // filtruje sa v Groovy.
    def id = (userId ?: "") as String
    if (!id) return null
    return findCases { it.processIdentifier.eq(siet("sd_firma")) }.find { c ->
        userIdsOf(c.dataSet["f_clenovia"]?.value).contains(id)
    }
}

{ def userId ->
    def mena = menaUzivatelov([userId as String])
    def m = mena ? (mena[0] as String) : ""
    return (m && m != "unknown unknown") ? m : (emailyOf([userId as String])[0] ?: (userId as String))
}

{ ->
    def u = loggedUser()
    return u == null ? "?" : meno_cloveka(u.stringId)
}

{ def tk_predmet ->
    // Cislo a predmet, BEZ stavu - Case.title sa neprekladá (RUNBOOK 9).
    def cislo = ((useCase.visualId ?: "") as String)
    def p = ((tk_predmet?.value ?: "") as String).trim()
    return p ? (cislo + " · " + p) : cislo
}

{ def pole, def text ->
    // Komunikacia sa len pripisuje, nikdy neprepisuje - je to historia poziadavky.
    def ked = java.time.LocalDateTime.now().format(
            java.time.format.DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm"))
    def stare = ((pole.value ?: "") as String)
    def riadok = ked + " · " + ja() + ": " + (text as String)
    return stare ? (stare + "\n\n" + riadok) : riadok
}

{ def pole, def sprava ->
    // Validacia v `pre`, ktoru `required` neoveri. Odmietnutie vrati HTTP 200
    // a dovod v tele ako `error`.
    if (!((pole.value ?: "") as String).trim()) {
        throw new java.lang.IllegalStateException(sprava as String)
    }
}

{ def firma, def priorita ->
    // Hodiny odozvy zo zmluvy firmy, inak standard.
    def p = ((priorita ?: "") as String).trim().toUpperCase()
    def standard = (["A": 2, "B": 4, "C": 8][p] ?: 8) as int
    if (firma == null || !(p in ["A", "B", "C"])) return standard
    def dohodnute = firma.dataSet["f_sla_" + p.toLowerCase()]?.value
    if (dohodnute == null) return standard
    int h = (dohodnute as Number).intValue()
    return h > 0 ? h : standard
}

{ def start, def hours ->
    // Pracovny cas Po-Pi 08:00-16:00. Sviatky tato verzia neriesi - patria
    // do kalendara v backendovej sluzbe, nie do Groovy akcie.
    if (start == null) return null
    def cur = start
    int remaining = ((hours as int) * 60)
    int guard = 0
    while (remaining > 0 && guard < 1000) {
        guard++
        if (cur.dayOfWeek.value >= 6) {
            cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        if (cur.hour < 8) {
            cur = cur.withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        if (cur.hour >= 16) {
            cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
            continue
        }
        def endOfDay = cur.withHour(16).withMinute(0).withSecond(0).withNano(0)
        long avail = java.time.temporal.ChronoUnit.MINUTES.between(cur, endOfDay)
        if (avail >= remaining) return cur.plusMinutes(remaining)
        remaining -= (avail as int)
        cur = cur.plusDays(1).withHour(8).withMinute(0).withSecond(0).withNano(0)
    }
    return cur
}

{ def priorita ->
    return (["A": "red", "B": "orange", "C": "blue"][priorita as String] ?: "blue") as String
}

{ def komu, def predmet, def telo ->
    // Notifikacia nesmie zhodit prechod - `notifikuj` nikdy nehadze a bez
    // SMTP vrati 0.
    notifikuj(komu, ((useCase.visualId ?: "") as String) + " - " + (predmet as String),
            (telo as String) + "\n\n" + ((useCase.title ?: "") as String))
}

actions.action:
tk_predmet: f.tk_predmet, tk_typ: f.tk_typ, tk_urgentnost: f.tk_urgentnost, tk_popis: f.tk_popis,
tk_zadavatel: f.tk_zadavatel, tk_firma_id: f.tk_firma_id, tk_firma_nazov: f.tk_firma_nazov,
tk_firma_ludia: f.tk_firma_ludia, tk_stav: f.tk_stav, tk_priorita: f.tk_priorita,
tk_podal: f.tk_podal, tk_podane_o: f.tk_podane_o, sla_termin: f.sla_termin,
tk_komunikacia: f.tk_komunikacia;

povinne(tk_predmet, "Fill in the subject.")
povinne(tk_typ, "Pick the kind of request.")
povinne(tk_urgentnost, "Pick how urgent it is.")
povinne(tk_popis, "Describe what you need.")

def autor = userIdsOf(tk_zadavatel.value)[0]
if (!autor) autor = loggedUser()?.stringId
// Firma sa overuje ZNOVA, nie z `tk_firma_id` z konceptu: medzi zalozenim
// a podanim mohol byt clovek z firmy odobraty alebo zmluva ukoncena.
def firma = firma_cloveka(autor)
if (firma == null) {
    throw new java.lang.IllegalStateException(
            "Your account is not assigned to any company, so the request has nowhere to go. Ask support to add you.")
}
if (firma.dataSet["f_aktivna"]?.value == false) {
    throw new java.lang.IllegalStateException(
            "The contract of your company is not active - new requests cannot be submitted.")
}
def ted = java.time.LocalDateTime.now()
def p = tk_urgentnost.value as String
change tk_firma_id value { firma.stringId }
change tk_firma_nazov value { ((firma.dataSet["f_nazov"]?.value ?: firma.title) as String) }
change tk_firma_ludia value { userIdsOf(firma.dataSet["f_clenovia"]?.value) }
change tk_priorita value { p }
change tk_stav value { "nova" }
change tk_podane_o value { ted }
change sla_termin value { business_deadline(ted, hodiny(firma, p)) }
change tk_komunikacia value { zapis(tk_komunikacia, "request submitted") }
changeCaseProperty("title").about { nazov(tk_predmet) }
changeCaseProperty("color").about { farba(p) }
oznam(usersWithRoleAll("podpora", useCase.processIdentifier as String),
        "new request from " + ((tk_firma_nazov.value ?: "") as String),
        ((tk_popis.value ?: "") as String))

tk_doplnenie: f.tk_doplnenie, tk_komunikacia: f.tk_komunikacia, tk_stav: f.tk_stav,
tk_riesitel_id: f.tk_riesitel_id;

povinne(tk_doplnenie, "Write your reply.")
def text = ((tk_doplnenie.value ?: "") as String).trim()
change tk_komunikacia value { zapis(tk_komunikacia, text) }
change tk_doplnenie value { "" }
change tk_stav value { "v_rieseni" }
def riesitel = ((tk_riesitel_id.value ?: "") as String)
if (riesitel) oznam([riesitel], "the customer replied", text)

tk_dovod: f.tk_dovod, tk_komunikacia: f.tk_komunikacia, tk_stav: f.tk_stav,
tk_riesitel_id: f.tk_riesitel_id, tk_priorita: f.tk_priorita;

povinne(tk_dovod, "Write why the request is not resolved.")
def text = ((tk_dovod.value ?: "") as String).trim()
change tk_komunikacia value { zapis(tk_komunikacia, "reopened: " + text) }
change tk_dovod value { "" }
change tk_stav value { "v_rieseni" }
changeCaseProperty("color").about { farba(tk_priorita.value) }
def riesitel = ((tk_riesitel_id.value ?: "") as String)
if (riesitel) oznam([riesitel], "the customer reopened the request", text)

tk_priorita: f.tk_priorita, tk_typ: f.tk_typ, tk_stav: f.tk_stav, tk_riesitel: f.tk_riesitel,
tk_riesitel_id: f.tk_riesitel_id, sla_prevzate: f.sla_prevzate, sla_termin: f.sla_termin,
sla_dodrzane: f.sla_dodrzane, tk_komunikacia: f.tk_komunikacia, tk_zadavatel: f.tk_zadavatel;

povinne(tk_priorita, "Pick the priority.")
povinne(tk_typ, "Pick the kind of request.")
def ted = java.time.LocalDateTime.now()
def termin = sla_termin.value
def ja_id = loggedUser()?.stringId as String
change tk_stav value { "v_rieseni" }
change tk_riesitel value { ja() }
change tk_riesitel_id value { ja_id }
change sla_prevzate value { ted }
change sla_dodrzane value { termin == null || !ted.isAfter(termin) }
change tk_komunikacia value { zapis(tk_komunikacia, "picked up the request") }
changeCaseProperty("color").about { farba(tk_priorita.value) }
oznam(tk_zadavatel, "your request is being handled", "Handled by: " + ja())

tk_otazka: f.tk_otazka, tk_komunikacia: f.tk_komunikacia, tk_stav: f.tk_stav,
tk_zadavatel: f.tk_zadavatel;

povinne(tk_otazka, "Write what you need from the customer.")
def text = ((tk_otazka.value ?: "") as String).trim()
change tk_komunikacia value { zapis(tk_komunikacia, text) }
change tk_stav value { "caka" }
changeCaseProperty("color").about { "purple" }
oznam(tk_zadavatel, "support needs your reply", text)

tk_komunikacia: f.tk_komunikacia, tk_stav: f.tk_stav, tk_priorita: f.tk_priorita;

change tk_komunikacia value { zapis(tk_komunikacia, "continuing without a written reply") }
change tk_stav value { "v_rieseni" }
changeCaseProperty("color").about { farba(tk_priorita.value) }

tk_riesenie: f.tk_riesenie, tk_komunikacia: f.tk_komunikacia, tk_stav: f.tk_stav,
tk_zadavatel: f.tk_zadavatel;

povinne(tk_riesenie, "Write how the request was resolved.")
def text = ((tk_riesenie.value ?: "") as String).trim()
change tk_komunikacia value { zapis(tk_komunikacia, "resolved: " + text) }
change tk_stav value { "vyriesena" }
changeCaseProperty("color").about { "green" }
oznam(tk_zadavatel, "your request is resolved", text)
